"use client";
import Component from "../smoothui/SearchableDropdown";
import { useState } from "react";
import { artworks } from "../shared/SampleArt";
import { FolderIcon } from "@phosphor-icons/react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [selected, setSelected] = useState("Pick a project");
  return (
    <DemoFrame hint={selected}>
      <Component
        label="Find a project"
        placeholder="Search projects…"
        items={artworks.map((art) => ({
          id: art.id,
          label: art.title,
          description: art.description,
          icon: <FolderIcon size={18} />,
        }))}
        onChange={(item) => setSelected(item.label)}
      />
    </DemoFrame>
  );
}

/** Original example artwork and composition. Copyright (c) 2026 NikroZorkin. MIT. */
export const artworks = [
  {
    id: "contours",
    title: "Quiet contours",
    src: "/media/art-01.svg",
    description: "A study in soft, repeating lines.",
  },
  {
    id: "orbit",
    title: "In orbit",
    src: "/media/art-02.svg",
    description: "Small shapes finding their balance.",
  },
  {
    id: "field",
    title: "Open field",
    src: "/media/art-03.svg",
    description: "A little room to wander.",
  },
  {
    id: "sunset",
    title: "After hours",
    src: "/media/art-04.svg",
    description: "Warm light at the end of the day.",
  },
  {
    id: "glass",
    title: "Soft focus",
    src: "/media/art-05.svg",
    description: "Light, layers, and a change of perspective.",
  },
  {
    id: "paper",
    title: "Paper studies",
    src: "/media/art-06.svg",
    description: "Collected shapes from the studio.",
  },
];

export function ArtTile({ index = 0 }: { index?: number }) {
  const art = artworks[index % artworks.length];
  return (
    <figure className="flex h-full flex-col overflow-hidden rounded-2xl border bg-background">
      <img
        src={art.src}
        alt={art.title}
        className="h-32 min-h-0 flex-1 w-full object-cover"
        width={400}
        height={280}
      />
      <figcaption className="shrink-0 p-3">
        <p className="text-[10px] uppercase tracking-widest text-muted-foreground">
          Studio collection
        </p>
        <h3 className="mt-1 font-medium text-base">{art.title}</h3>
        <p className="mt-1 text-xs text-muted-foreground">{art.description}</p>
      </figcaption>
    </figure>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

